function tf = isGeneratedClassFile(filePath)
%isGeneratedClassFile True if optionspec.generateClasses wrote the file.
%
%   The header of a generated class has the line
%   "%   Generated by optionspec.generateClasses from definition ...".

    arguments
        filePath (1,1) string
    end

    fileId = fopen(filePath, "r", "n", "UTF-8");
    if fileId == -1
        tf = false;
        return
    end
    closeFile = onCleanup(@() fclose(fileId));
    text = string(fread(fileId, [1, Inf], "*char"));
    tf = contains(text, "%   Generated by optionspec.generateClasses from definition");
end
